// 分项课在界面上：课程页、聊天里的上课条和卡片、练习、限时写作、批改单（docs/COURSE-KERNEL.md 7.6）。
// Written by the project lead as the executable spec. Do not edit this file to make it pass; change the implementation.
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {createMock} from './ui/mock-api.mjs';
const {chromium} = await import(process.env.LANGPAL_PLAYWRIGHT_MODULE || 'playwright-core');
const root = process.env.LANGPAL_SOURCE_ROOT || path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const types = {'.html':'text/html; charset=utf-8','.js':'text/javascript','.mjs':'text/javascript','.css':'text/css','.svg':'image/svg+xml','.png':'image/png','.ttf':'font/ttf','.json':'application/json'};
const lesson = JSON.parse(await fs.readFile(path.join(root, 'backend/app/data/lessons/toefl-2026/writing-email.json'), 'utf8'));
const browser = await chromium.launch({executablePath:process.env.LANGPAL_CHROME_PATH || undefined,headless:true,args:['--mute-audio']});
const calls = [], errors = [];
const ESSAY = 'Dear Ms. Rivera, I signed up for the photography workshop last Monday and I paid the fee, but I did not get any email. Please tell me what should I do before Saturday.';
try {
  const page = await browser.newPage({viewport:{width:1100,height:760}});
  page.setDefaultTimeout(8000);
  page.on('pageerror', error => errors.push(error.message));
  const {handle} = createMock({solo:true});
  await page.route('**/*', async route => {
    const request = route.request(), url = new URL(request.url());
    assert.equal(url.hostname, 'lesson.test');
    if (url.pathname.startsWith('/api/')) {
      const body = request.postData();
      calls.push({method:request.method(),path:url.pathname,body:body ? JSON.parse(body) : null});
      const result = handle(request.url(),request.method(),body);
      if (!result) return route.fulfill({status:404,json:{detail:'mock'}});
      return result.json !== undefined ? route.fulfill({status:result.status,json:result.json})
        : route.fulfill({status:result.status,contentType:result.contentType,body:result.body});
    }
    const file = path.join(root,'frontend',url.pathname === '/' ? 'index.html' : decodeURIComponent(url.pathname));
    try { return route.fulfill({contentType:types[path.extname(file)] || 'application/octet-stream',body:await fs.readFile(file)}); }
    catch { return route.fulfill({status:404,body:''}); }
  });
  const posts = (name) => calls.filter(call => call.method === 'POST' && call.path === '/api/teaching/lesson/' + name);
  const proactive = () => calls.filter(call => call.path === '/api/chat/proactive').length;
  let cardId = 'facts';
  const current = () => page.locator('#page-course .jm-card[data-card=' + cardId + ']');
  await page.goto('http://lesson.test/');
  await page.waitForSelector('#jine-messages .jm-row');
  await page.locator('#jm-dial [lang=en]').click();
  await page.waitForFunction(() => document.querySelector('#jm-dial [lang=en]').getAttribute('aria-checked') === 'true');

  // 1. 课程页：分项课按部分列出每一节课，只读，有进度和「上这一课」
  await page.evaluate(async () => { await LP.settings.open('library'); await LP.settingsTeaching.setLanguage('en'); });
  await page.waitForSelector('.course-section');
  assert.match(await page.locator('.course-paper-meta').innerText(), /已掌握 0 \/ 3/);
  assert.deepEqual(await page.locator('.course-section').allTextContents(), ['写作']);       // 还没有课的部分不显示
  assert.equal(await page.locator('.course-paper input, .course-paper textarea').count(), 0); // 分项课不能逐字段改
  assert.equal(await page.locator('.course-unit > summary strong').first().innerText(), lesson.title);
  assert.equal(await page.locator('.course-unit-state').first().getAttribute('aria-label'), '');
  await page.locator('.course-unit > summary').first().click();
  assert.deepEqual(await page.locator('.course-unit-actions button').allTextContents(), ['上这一课']);
  assert.deepEqual(await page.locator('.course-knowledge h4').allTextContents(), lesson.points.map(p => p.label));
  assert.equal(await page.locator('.course-next b').innerText(), '上第 1 课');

  // 2. 开课：课程页显示整节课，她不说开场白
  const before = proactive();
  await page.locator('.course-next').click();
  await page.waitForSelector('#page-course.active .cp-body .jm-card');
  assert.deepEqual(posts('start').at(-1).body, {language:'en',lesson_id:'writing-email'});
  assert.equal(await page.locator('.cp-intro h1').innerText(), lesson.title);
  await page.waitForSelector('#page-course .jm-card[data-card=facts][open]');
  assert.equal(await page.locator('#page-course .jm-card').count(), lesson.cards.length);
  assert.equal(await current().locator('.lc-row').count(), lesson.cards[0].rows.length);
  await page.waitForFunction(() => !document.querySelector('.jm-typing'));
  assert.equal(proactive(), before);

  cardId = 'rubric';
  assert.equal(await current().locator('.lc-level').count(), 6);

  // 4. 范文卡：引用处有底色和序号
  cardId = 'models';
  await page.waitForSelector('.jm-card[data-card=models][open]');
  const five = lesson.cards.find(c => c.id === 'models').responses[0];
  assert.equal(await current().locator('.lc-response').first().locator('mark.good').count(), five.notes.length);
  assert.equal(await current().locator('.lc-task li').count(), 3);

  // 5. 练习卡：一题一个输入框，判完显示改法和参考答案；刷新后还在
  cardId = 'drill-correct';
  await page.waitForSelector('.jm-card[data-card=drill-correct][open]');
  const first = current().locator('.lc-items li').first();
  await first.locator('textarea').fill('I very much like the new schedule.');
  await first.locator('.lc-go').click();
  await first.locator('.lc-check .no').waitFor();
  assert.deepEqual(posts('answer').at(-1).body, {
    run_id:await page.evaluate(() => LP.lesson.current().id),card:'drill-correct',item:0,text:'I very much like the new schedule.'
  });
  assert.equal(await first.locator('.lc-check .fix').count(), 1);
  assert.equal(await first.locator('.lc-fold summary').innerText(), '参考答案');
  await first.locator('textarea').fill('right: I really like the new schedule.');
  await first.locator('.lc-go').click();
  await first.locator('.lc-check .ok').waitFor();
  assert.equal(await first.locator('.lc-check .fix').count(), 0);
  await page.reload();
  await page.waitForSelector('.jm-card[data-card=drill-correct][open]');
  assert.equal(await page.locator('.jm-card[data-card=drill-correct] .lc-items li textarea').first().inputValue(), 'right: I really like the new schedule.');
  assert.equal(await page.locator('#page-course .jm-card').count(), lesson.cards.length);

  // 6. 限时写作：点开始才出题、才走表；太短不交；交卷后原地出批改单
  cardId = 'timed';
  await page.waitForSelector('.jm-card[data-card=timed][open] .lc-begin');
  assert.equal(await current().locator('.lc-next').count(), 0);
  assert.equal(await current().locator('.lc-writing').isVisible(), false);
  assert.equal(await current().locator('.lc-timer').innerText(), '7:00');
  await current().locator('.lc-begin').click();
  await current().locator('.lc-writing .lc-task').waitFor();
  await page.waitForFunction(() => /^6:5\d$/.test(document.querySelector('.jm-card[data-card=timed] .lc-timer').textContent));
  const essay = current().locator('.lc-essay');
  assert.equal(await essay.getAttribute('spellcheck'), 'false');
  await essay.fill('Hello, thank you.');
  assert.equal(await current().locator('.lc-count').innerText(), '3 词');
  await current().locator('.lc-writing .lc-go').click();
  assert.equal(await current().locator('.lc-notice').innerText(), '写得太少，没法批改');
  assert.equal(posts('submit').length, 0);
  await essay.fill(ESSAY);
  const spoke = proactive();
  await current().locator('.lc-writing .lc-go').click();
  await page.waitForSelector('.jm-card[data-card=timed] .lc-sheet');
  const sent = posts('submit').at(-1).body;
  assert.equal(sent.text, ESSAY);
  assert.equal(Number.isInteger(sent.seconds) && sent.seconds >= 0 && sent.seconds <= 420, true);
  const done = page.locator('.jm-card[data-card=timed]');
  assert.deepEqual(await done.locator('.lc-sheet h4').allTextContents(), ['一、题目的要求','二、分数档','三、必改的地方','四、升一档']);
  assert.equal(await done.locator('.lc-sheet .lc-verdict').count(), 3);
  assert.equal(await done.locator('.lc-sheet .lc-score').innerText(), '3');
  assert.deepEqual(await done.locator('.lc-fold > summary').allTextContents(), ['得分要点','5 分范文']);
  assert.equal(await done.locator('.lc-essay').count(), 0);
  // 课程页上交的卷：她不在聊天里接话
  await page.evaluate(() => LP.appShell.switchTab('talk'));
  await page.waitForTimeout(800);
  assert.equal(proactive(), spoke);
  await page.evaluate(() => LP.appShell.switchTab('course'));
  // 7. 收起：返回目录
  await page.click('.cp-back');
  await page.waitForFunction(() => document.querySelector('.cp-lesson').hidden);
  assert.equal(posts('stop').length, 1);
  assert.equal(await page.locator('#page-course .jm-card').count(), 0);

  // 8. 她也能开课
  assert.deepEqual(await page.evaluate(() => LP.actions.run('lesson')), {ok:true,label:'▶ 上课'});
  assert.deepEqual(posts('start').at(-1).body, {language:'en'});
  await page.waitForSelector('#page-course.active .cp-body .jm-card');
  await page.click('.cp-back');
  assert.deepEqual(errors, []);
  console.log('PASS lesson: course page, bar, cards, drill, timed writing, sheet.');
} finally { await browser.close(); }
